/**
 * Every film on the site, with where it came from and whether ARCHIFORM has the right to use it.
 * The home page reads its video sources, descriptions and on-screen disclosure from here.
 *
 * origin   'ai'           AI-generated (tool not recorded)
 *          'google-flow'  generated by ARCHIFORM with Google Flow (AI)
 *          'pinterest'    downloaded from Pinterest; the creator's licence is needed before publishing
 *          'mixed'        edited together from more than one of the above
 *          'unconfirmed'  source not yet recorded; treat as unlicensed until confirmed
 * source   where the file came from, when not made by the studio (e.g. 'pinterest')
 * rights   'owned' | 'licensed' | 'unverified'
 *
 * src/poster are the landscape cuts (desktop, landscape tablets); msrc/mposter the portrait cuts (phones, portrait tablets).
 * DISCLOSURE / disclosureFor give the label for a film's origin; the page does not show it at present.
 */
export const DISCLOSURE = {
  ai: 'AI-generated visualisation',
  'google-flow': 'AI-generated visualisation',
  mixed: 'Illustrative film, partly AI-generated',
  pinterest: 'Illustrative film',
  unconfirmed: 'Illustrative film',
};

